def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 18.0))

    opp_prev_bids = []
    desperate_count = 0
    rich_count = 0
    req_pressure = 0.0

    for oid, opp in alive:
        if opp.get('budget', 0) >= 180:
            rich_count += 1
        req_pressure += float(opp.get('water_requirement', WATER_REQ))
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid')
            if bid is not None:
                opp_prev_bids.append(float(bid))
            status = prev.get('status')
            hp_after = prev.get('hp_after')
            if status == 'no_water' or (hp_after is not None and hp_after <= 3):
                desperate_count += 1

    highest_prev = max(opp_prev_bids) if opp_prev_bids else 0.0
    avg_prev = sum(opp_prev_bids) / len(opp_prev_bids) if opp_prev_bids else 0.0

    slots = max(1, int(supply // WATER_REQ))
    total_players = 1 + len(alive)
    scarcity = total_players - slots

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water_days >= 2:
        urgency += 4
    elif no_water_days >= 1:
        urgency += 2
    if supply <= 16:
        urgency += 3
    elif supply <= 19:
        urgency += 2
    if scarcity >= 3:
        urgency += 2
    elif scarcity >= 2:
        urgency += 1
    if desperate_count >= 2:
        urgency += 1

    conservative_bid = max(12.0, min(32.0, 0.22 * DAILY_SALARY + 0.06 * avg_prev))
    medium_bid = max(38.0, min(78.0, 0.52 * DAILY_SALARY + 0.18 * highest_prev))
    aggressive_bid = max(72.0, min(140.0, highest_prev + 6.0))
    all_in_bid = max(95.0, min(0.92 * budget, highest_prev + 15.0))

    bob_like_pressure = highest_prev >= 120.0 or avg_prev >= 90.0 or rich_count >= 2

    if urgency >= 7:
        bid = all_in_bid
    elif urgency >= 5:
        bid = aggressive_bid if bob_like_pressure else max(medium_bid, 68.0)
    elif urgency >= 3:
        if supply <= 18:
            bid = max(medium_bid, highest_prev * 0.72 + 4.0)
        else:
            bid = medium_bid
    else:
        if highest_prev >= 150.0 and hp >= 5:
            bid = conservative_bid
        elif supply >= 24 and hp >= 6:
            bid = min(conservative_bid, 24.0)
        else:
            bid = max(conservative_bid, min(44.0, avg_prev * 0.45 + 8.0))

    if day >= 8:
        if hp <= 4 or no_water_days >= 1:
            bid = max(bid, aggressive_bid)
        elif budget < 90:
            bid = min(bid, 36.0)

    if budget < 60:
        bid = min(bid, max(18.0, 0.72 * budget))

    bid = min(float(budget), float(bid))
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    # Alive opponents and yesterday bids
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    yesterday_bids = []
    yesterday_pressures = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        bid = prev.get('bid', None)
        if bid is not None:
            yesterday_bids.append(float(bid))
        # Use hp_after as a proxy for how costly yesterday was for them
        hp_after = prev.get('hp_after', None)
        if hp_after is not None:
            yesterday_pressures.append(float(hp_after))

    # Determine supply tightness
    # At low supply, bid more to avoid being outcompeted.
    supply_tight = (supply <= (MIN_SUPPLY + MAX_SUPPLY) / 2.0)  # <= 20

    # If we are low HP, prioritize survival.
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])

    # Estimate how aggressive others were yesterday.
    if yesterday_bids:
        avg_prev = sum(yesterday_bids) / float(len(yesterday_bids))
        max_prev = max(yesterday_bids)
    else:
        avg_prev = 0.0
        max_prev = 0.0

    # Base target bid: mid-high when supply is tight, else moderate.
    # Also react to yesterday aggression: if someone bid very high, slightly increase.
    if supply_tight:
        base = DAILY_SALARY * 0.75
    else:
        base = DAILY_SALARY * 0.55

    # If max_prev indicates strong contention, match closer.
    if max_prev >= DAILY_SALARY * 1.6:
        base = max(base, DAILY_SALARY * 0.85)
    elif avg_prev >= DAILY_SALARY * 1.2:
        base = max(base, DAILY_SALARY * 0.7)

    # Survival adjustment
    if hp <= 2.0:
        base = max(base, DAILY_SALARY * 0.95)
    elif hp <= 4.0:
        base = max(base, DAILY_SALARY * 0.8)

    # Budget cap: never exceed remaining budget.
    # Also avoid spending everything early unless critically low HP.
    if hp <= 2.0:
        cap = budget
    else:
        cap = min(budget, DAILY_SALARY * 3.0)

    bid = min(cap, base)

    # If budget is extremely low, bid proportionally to avoid zero.
    if budget <= DAILY_SALARY * 0.2:
        bid = min(budget, max(1.0, budget * 0.9))

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return float(bid)
